import type { UserProfile, EligibilityResult } from '@/types'
import { getAllSchemes } from './scheme-service'

/**
 * Calls the XGBoost-based backend service to evaluate scheme eligibility.
 * 
 * @param profile The UserProfile generated by the form submission.
 * @returns A promise resolving to mapped EligibilityResult objects.
 */
export async function predictEligibility(profile: UserProfile): Promise<EligibilityResult[]> {
  try {
    const response = await fetch('/api/eligibility/predict', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(profile),
    })

    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`)
    }

    const data = await response.json()
    if (!data || !Array.isArray(data.predictions)) {
      throw new Error('Invalid predictions response payload from service.')
    }

    const schemes = getAllSchemes()

    return data.predictions
      .filter((pred: any) => pred.status === 'eligible')
      .map((pred: any) => {
        const scheme = schemes.find((s) => s.id === pred.scheme_id || s.slug === pred.scheme_id)
        if (!scheme) {
          console.warn(`Scheme ID "${pred.scheme_id}" from ML service not found in the local schemes database.`)
          return null
        }

        return {
          scheme,
          status: 'eligible',
          score: pred.score,
          matchedCriteria: ['Based on the information provided, this scheme received a high model score.'],
          missedCriteria: [],
        } as EligibilityResult
      })
      .filter((res): res is EligibilityResult => res !== null)
  } catch (error) {
    console.error('Error in ML eligibility service:', error)
    throw new Error('AI eligibility service is currently unavailable. Please try again.')
  }
}
